const button=document.querySelector('.menu');const nav=document.querySelector('nav');button.addEventListener('click',()=>{const open=button.getAttribute('aria-expanded')!=='true';button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Fermer le menu':'Ouvrir le menu');nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{button.setAttribute('aria-expanded','false');button.setAttribute('aria-label','Ouvrir le menu');nav.classList.remove('open')}));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&nav.classList.contains('open')){button.click();button.focus()}});
